def transform(grid):
    h, w = len(grid), len(grid[0])
    border = grid[0][0]
    tw = next(c for c in range(1, w) if grid[1][c] == border) + 1
    th = next(r for r in range(1, h) if grid[r][1] == border) + 1
    result = []
    for y in range(0, h, th):
        band = grid[y:y + th]
        tiles = [[row[x:x + tw] for row in band] for x in range(0, w, tw)]
        # Treat the repeated glyph as the template and overlay its deviations.
        chosen = [row[:] for row in max(tiles, key=lambda t: tiles.count(t))]
        for tile in tiles:
            for r in range(th):
                for c in range(tw):
                    if tile[r][c] != chosen[r][c]:
                        chosen[r][c] = tile[r][c]
        result.extend(chosen)
    return result
